import{_ as i,o as l,c as n,j as a,a as o,G as t,aa as r,B as c}from"./chunks/framework.VLjJFeoF.js";const C=JSON.parse('{"title":"浏览器","description":"","frontmatter":{},"headers":[],"relativePath":"docs/interview/browser/index.md","filePath":"docs/interview/browser/index.md","lastUpdated":1770685239000}'),p={name:"docs/interview/browser/index.md"};function d(u,e,h,m,b,g){const s=c("ArticleMetadata");return l(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1770685239000"},[e[0]||(e[0]=a("h1",{id:"浏览器",tabindex:"-1"},[o("浏览器 "),a("a",{class:"header-anchor",href:"#浏览器","aria-label":'Permalink to "浏览器"'},"​")],-1)),t(s,{article:{}}),e[1]||(e[1]=r(`<h2 id="_1-浏览器进程有哪些" tabindex="-1">1.浏览器进程有哪些 <a class="header-anchor" href="#_1-浏览器进程有哪些" aria-label="Permalink to &quot;1.浏览器进程有哪些&quot;">​</a></h2><p>浏览器是多进程架构的，每个标签页是独立的渲染进程</p><ul><li>浏览器主进</li><li><strong>渲染进程</strong><ul><li>GUI 渲染线程：渲染页面，和 JS 引擎互斥</li><li>JS 引擎线程：执行 JS 代码</li><li>事件触发线程：主要用来控制事件循环，比如 JS 执行遇到计时器，AJAX 异步请求等，就会将对应任务添加到事件触发线程。在对应事件符合触发条件触发时，就把事件添加到待处理队列的队尾，等 JS 引擎处理</li><li>定时触发器线程: setTimeout/setInterval</li><li>异步 HTTP 请求线程:</li></ul></li><li>GPU 进程</li><li>网络进程</li><li>插件进程</li></ul><h2 id="_2-事件循环机制" tabindex="-1">2.事件循环机制 <a class="header-anchor" href="#_2-事件循环机制" aria-label="Permalink to &quot;2.事件循环机制&quot;">​</a></h2><p>JS 是单线程的语言，只有一个执行栈，先执行当前任务，遇到异步事件就放入任务队列中，分为宏任务和微任务，当前宏任务执行完会处理所有的微任务，再从宏任务队列中取一个开始下一个宏任务。</p><ul><li>渲染是下一个宏任务执行前 <a href="https://zhuanlan.zhihu.com/p/78113300" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/78113300</a></li></ul><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./img/1654402275546-74fadbb4-590b-42cb-9079-9df66ae710ed.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;200&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;margin: 0 auto;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>宏任务：script 标签 / 交互事件</p><ul><li><code>setTimeout()</code> / <code>setInterval()</code> /<code>requestAnimationFrame()</code> /  <strong>Node</strong>: <code>setImmediate()</code></li></ul><p>微任务：</p><ul><li><code>Promise()</code>  / <code>MutationObserver()</code> / <code>queueMicrotask()</code> /  <strong>Node</strong>: <code>process.nextTick()</code></li></ul><p>Node:</p><ul><li><code>Node11</code>开始，每执行完一个 <code>timers</code> 类回调，例如 <code>setTimeout</code> /<code>setImmediate</code> 之后，都会把微任务给执行掉（promise 等）</li></ul><h3 id="事件循环" tabindex="-1">事件循环 <a class="header-anchor" href="#事件循环" aria-label="Permalink to &quot;事件循环&quot;">​</a></h3><p>Node 的事件循环是由 libuv 实现的，每一轮的事件循环有 6 个阶段，每个阶段都有一个 FIFO 的执行回调的队列。</p><p>关键阶段：<strong>timers</strong>: setTimout/setInterval 、<strong>poll</strong>: 执行回调 / 检查定时器 、 <strong>check</strong>:setImmediate</p><ul><li><p>Node11 调整与浏览器结果一致，每执行完一个 timers 类任务 就执行微任务</p><ul><li>之前是：所有 timers 类任务 都执行完了，再执行微任务</li></ul></li><li><p>process.nextTick 是一个单独的队列，每个阶段执行完 都会执行 process.nextTick 的队列，优先级大于 Promise</p></li><li><p>setImmediate 和 setTimeout</p><ul><li>在 poll 处理的回调中 先 setImmediate 后 setTimeout ，否则（在主脚本）顺序是不确定的</li></ul></li></ul><h2 id="_3-浏览器存储" tabindex="-1">3.浏览器存储 <a class="header-anchor" href="#_3-浏览器存储" aria-label="Permalink to &quot;3.浏览器存储&quot;">​</a></h2><p><strong>Cookie</strong>：</p><p>主要用于，会话状态管理，用户跟踪。 缺点：空间小 4K 限制；网络请求会携带影响性能；安全和隐私问题，如 CSRF</p><ul><li><code>Domain</code>/<code>Path</code> 定义了 Cookie 的作用域</li><li>可设置有效期（<code>Expires</code>/<code>Max-Age</code>）</li><li><code>HttpOnly</code> 限制 JS 访问（<code>document.cookie</code>），减少 XSS 风险</li><li><code>Secure</code> 标记为只能通过 HTTPS 发送</li></ul><p>第三方 Cookie 的问题：</p><ul><li><code>SameSite</code> 限制三方 Cookie 在跨站（顶级域名不同）请求时不会被发送，http 不支持，需要同时设置<code>Secure</code><ul><li><code>Strict</code> 不允许跨站</li><li><code>Lax</code> 允许部分请求,如 <code>a</code>、<code>link</code></li><li><code>None</code> 不限制</li><li>Chrome 80+ 默认是 <code>Lax</code></li></ul></li><li>Chrome 新版本浏览器停用第三方 Cookie</li><li>Chrome 114 增加了 Cookie 独立分区 新属性，<code>Partitioned</code>, 第三方 cookie 可以用。 跨站不共享</li></ul><blockquote><p>操作：document.cookie 读取/或写入，写入是追加</p></blockquote><p><strong>LocalStorage/SessionStorage</strong>：5M</p><ul><li>浏览器提供的本地存储方法，同源策略，API 简单</li><li>SessionStorage：当前窗口关闭就失效了，多个同源页面不共享</li><li>localStorage：永久保存，同源页面共享</li><li>缺点：空间小，只能存字符串</li></ul><blockquote><p>方法：setItem/getItem/removeItem/clear</p></blockquote><p><strong>IndexedDB</strong>：用于客户端存储大量结构化数据，采用键值存储，接近 NoSQL 数据库，同源策略，支持异步，支持事务，空间大（不少于 250M）</p><h2 id="_4-怎么解决跨域问题" tabindex="-1">4.怎么解决跨域问题 <a class="header-anchor" href="#_4-怎么解决跨域问题" aria-label="Permalink to &quot;4.怎么解决跨域问题&quot;">​</a></h2><p>同源策略指的是：协议+域名+端口</p><p><strong>JSONP(手写)</strong></p><ul><li>前端构建一个全局函数的回调 promise</li><li>服务端返回一个传入数据的调用函数的字符串，浏览器接收后执行</li></ul><blockquote><p>仅支持 get，不安全</p></blockquote><p><strong>CORS</strong> 跨域资源共享（CORS，Cross-Origin Resource Sharing） 在服务端允许跨域的情况下，通过 HTTP 响应头告诉浏览器当前请求允许跨域。</p><p><code>简单请求</code>：</p><ul><li>请求方法为 <strong>GET</strong>、<strong>POST</strong>、<strong>HEAD</strong>。</li><li>请求头只能使用下面的字段： <ul><li>Accept</li><li>Accept-Language</li><li>Content-Type （只限于 text/plain、multipart/form-data、application/x-www-form-urlencoded）</li><li>Content-Language</li></ul></li></ul><p>任意一条要求不符合的即为<code>非简单请求</code></p><ul><li>非简单请求会先发个预检请求（Preflight）</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 简单请求：</span></span>
<span class="line"><span>请求头：Origin</span></span>
<span class="line"><span>响应头：Access-Control-Allow-Origin</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 预检请求</span></span>
<span class="line"><span>请求头：Method：OPTIONS</span></span>
<span class="line"><span>Access-Control-Request-Headers:content-type</span></span>
<span class="line"><span>Access-Control-Request-Methods:POST</span></span>
<span class="line"><span></span></span>
<span class="line"><span>响应头:</span></span>
<span class="line"><span>Access-Control-Allow-Headers: content-type</span></span>
<span class="line"><span>Access-Control-Allow-Origin: *</span></span>
<span class="line"><span>Access-Control-Request-Methods: POST,GET,OPTIONS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><ul><li>CORS 携带 Cookie <ul><li>预检的响应头里要 <code>Access-Control-Allow-Credentials: true</code></li><li>\`Access-Control-Allow-Origin 不能为空</li><li>在请求中设置 <code>withCredentials</code></li></ul></li></ul><p><strong>代理转发</strong></p><ul><li>正向代理</li><li>反向代理</li></ul><h2 id="_5-浏览器缓存策略" tabindex="-1">5.浏览器缓存策略 <a class="header-anchor" href="#_5-浏览器缓存策略" aria-label="Permalink to &quot;5.浏览器缓存策略&quot;">​</a></h2><p>浏览器缓存查找优先级：Service Worker / Memory Cache（浏览器自己控制） / Disk Cache（<strong>HTTP 缓存</strong>） / Push Cache（HTTP2）</p><h3 id="http-缓存" tabindex="-1">HTTP 缓存 <a class="header-anchor" href="#http-缓存" aria-label="Permalink to &quot;HTTP 缓存&quot;">​</a></h3><p><strong>强缓存</strong>：</p><ul><li>1.0 响应头 <code>Expires</code> 由客户端时间决定是否失效,不可取</li><li><code>Pragma:nocache</code></li><li>1.1 <code>Cache-Control: max-age=120;no-store/no-cache;private/public</code></li><li>没有缓存，浏览器会启发式缓存，</li></ul><p><strong>协商缓存</strong>：</p><p>文件内容</p><ul><li><p>请求 <code>Etag</code></p></li><li><p>首次响应返回 <code>If-None-Match</code></p><p>修改时间</p></li><li><p>请求 <code>If-Modifief-Since</code></p></li><li><p>首次响应返回 <code>Last-Modified</code></p></li></ul><p>F5: html 走<code>max-age=0</code>, 其他走缓存机制</p><p>ctrl+F5: <code>Cache-Control:no-cache;Pragma:no-cache</code></p><p><code>max-age=0</code>会走协商缓存，<code>no-cache</code> 重新请求</p><h3 id="service-worker" tabindex="-1">Service Worker <a class="header-anchor" href="#service-worker" aria-label="Permalink to &quot;Service Worker&quot;">​</a></h3><blockquote><p>Service Worker 拦截请求资源, 并约定缓存请求的策略</p></blockquote><h2 id="_6-浏览器渲染过程" tabindex="-1">6.浏览器渲染过程 <a class="header-anchor" href="#_6-浏览器渲染过程" aria-label="Permalink to &quot;6.浏览器渲染过程&quot;">​</a></h2><p>关键渲染路径（CRP）：创建 DOM 树/创建 CSSOM 树 - 生成渲染树 - 布局 - 绘制</p><ul><li>解析 HTML 和 CSS 分别生成 <code>DOM 树</code>和 <code>CSSOM 树</code></li><li>组装成 <code>render 树</code>，只添加可见的节点</li><li><code>布局Layout</code> ：计算出 节点的布局信息（大小和位置）,生产布局树</li><li>通过布局树，进行分层生成图层树</li><li><code>绘制</code>：为每个图层生成绘制列表，绘制节点的外观（颜色等）等</li><li><code>合成</code>：将图层划分图块，光栅化（转位图），发送绘制命令浏览进程，渲染显示</li></ul><blockquote><p>结合性能优化回答</p></blockquote><blockquote><p>CSS 会阻塞渲染吗</p><ul><li>CSS 不会阻塞 DOM 解析（link 在 head 中）</li><li>CSS 会阻塞 DOM 树的渲染（阻塞 render tree 的形成）</li><li>会阻塞后面的 JS 的执行（JS 可以更改 DOM 样式）</li></ul></blockquote><h2 id="_7-raf-ric" tabindex="-1">7.rAF/rIC <a class="header-anchor" href="#_7-raf-ric" aria-label="Permalink to &quot;7.rAF/rIC&quot;">​</a></h2><ul><li><code>requestAnimationFrame</code>：告诉浏览器在下一次绘制之前执行</li><li><code>requestIdleCallback</code>：在浏览器空闲的事件执行</li></ul>`,62))])}const S=i(p,[["render",d]]);export{C as __pageData,S as default};
